package id.roomfinds.api;

import jakarta.servlet.http.HttpSession;
import java.util.List;
import java.util.Map;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api")
public class WorkflowController {
    private final JdbcTemplate db;
    public WorkflowController(JdbcTemplate db) { this.db=db; }
    private long user(HttpSession s) { Object id=s.getAttribute("userId"); if(id==null) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"Silakan masuk untuk melanjutkan."); return (long)id; }
    private void owner(HttpSession s) { if(!"PEMILIK".equals(s.getAttribute("role"))) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Menu ini hanya tersedia untuk pemilik kos."); }
    private void admin(HttpSession s) { if(!"SUPERADMIN".equals(s.getAttribute("role"))) throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.FORBIDDEN,"Menu ini hanya tersedia untuk SuperAdmin."); }
    private long ownerId(HttpSession s) { owner(s); return user(s); }
    private void requireOwnedKos(long kosId, long ownerId) {
        if (db.queryForObject("SELECT COUNT(*) FROM kos WHERE id=? AND pemilik_id=?", Long.class, kosId, ownerId) == 0)
            throw new IllegalArgumentException("Kos tidak ditemukan atau kamu tidak memiliki akses.");
    }
    @GetMapping("/kos/{kosId}/booking") List<Map<String,Object>> ownerBookings(HttpSession s,@PathVariable long kosId) { long uid=ownerId(s); requireOwnedKos(kosId,uid); return db.queryForList("SELECT b.id,b.tanggal_masuk AS \"tanggalMasuk\",b.tanggal_selesai AS \"tanggalSelesai\",b.total_sewa AS \"totalSewa\",b.status,b.aturan_disetujui_pada AS \"waktuSetujuAturan\",km.nomor AS \"kamarNomor\",km.tipe,p.nama AS \"penyewaNama\",p.email,p.no_hp AS \"noHp\",ps.nama AS \"paketNama\" FROM booking b JOIN kamar km ON km.id=b.kamar_id JOIN pengguna p ON p.id=b.penyewa_id JOIN paket_sewa ps ON ps.id=b.paket_id WHERE km.kos_id=? ORDER BY b.dibuat_pada DESC",kosId); }
    @PatchMapping("/booking/{id}/batal") Map<String,Object> cancel(HttpSession s,@PathVariable long id) { long uid=user(s); db.update("UPDATE booking SET status='DIBATALKAN' WHERE id=? AND penyewa_id=? AND status='MENUNGGU'",id,uid); db.update("UPDATE kamar SET status='KOSONG' WHERE id=(SELECT kamar_id FROM booking WHERE id=? AND status='DIBATALKAN')",id); return db.queryForMap("SELECT * FROM booking WHERE id=? AND penyewa_id=?",id,uid); }
    @PatchMapping("/booking/{id}/checkout") @Transactional Map<String,Object> checkout(HttpSession s,@PathVariable long id) { owner(s); var row=db.queryForMap("SELECT b.id,b.kamar_id FROM booking b JOIN kamar km ON km.id=b.kamar_id JOIN kos k ON k.id=km.kos_id WHERE b.id=? AND k.pemilik_id=? AND b.status='DISETUJUI'",id,user(s)); Long due=db.queryForObject("SELECT COALESCE(SUM(total-terbayar),0) FROM tagihan WHERE booking_id=?",Long.class,id); if(due!=null&&due>0) throw new IllegalArgumentException("Check-out belum dapat dilakukan karena masih ada tagihan yang belum lunas."); db.update("UPDATE booking SET status='SELESAI' WHERE id=?",id); db.update("UPDATE kamar SET status='KOSONG' WHERE id=?",row.get("kamar_id")); return db.queryForMap("SELECT * FROM booking WHERE id=?",id); }
    @GetMapping("/pembayaran/riwayat") List<Map<String,Object>> paymentHistory(HttpSession s) { long uid=user(s); if("PEMILIK".equals(s.getAttribute("role"))) return db.queryForList("SELECT p.id,p.tagihan_id AS \"tagihanId\",p.metode,p.jumlah,p.tanggal,p.status,p.bank_asal AS \"bankAsal\",p.nama_pengirim AS \"namaPengirim\",p.catatan_verifikasi AS \"catatanVerifikasi\",u.nama AS \"penyewaNama\" FROM pembayaran p JOIN tagihan t ON t.id=p.tagihan_id JOIN booking b ON b.id=t.booking_id JOIN pengguna u ON u.id=b.penyewa_id JOIN kamar km ON km.id=b.kamar_id JOIN kos k ON k.id=km.kos_id WHERE k.pemilik_id=? ORDER BY p.tanggal DESC",uid); return db.queryForList("SELECT p.id,p.tagihan_id AS \"tagihanId\",p.metode,p.jumlah,p.tanggal,p.status,p.bank_asal AS \"bankAsal\",p.nama_pengirim AS \"namaPengirim\",p.catatan_verifikasi AS \"catatanVerifikasi\" FROM pembayaran p JOIN tagihan t ON t.id=p.tagihan_id JOIN booking b ON b.id=t.booking_id WHERE b.penyewa_id=? ORDER BY p.tanggal DESC",uid); }
    @GetMapping("/penundaan") List<Map<String,Object>> delays(HttpSession s) { long uid=user(s); if("PEMILIK".equals(s.getAttribute("role"))) return db.queryForList("SELECT d.id,d.tagihan_id AS \"tagihanId\",d.tanggal_diminta AS \"tanggalDiminta\",d.alasan,d.status,d.catatan_pemilik AS \"catatanPemilik\",d.dibuat_pada AS \"dibuatPada\",t.periode,t.jatuh_tempo AS \"jatuhTempo\",t.total,t.total-t.terbayar AS sisa,km.nomor AS \"kamarNomor\",k.nama AS \"kosNama\",p.nama AS \"penyewaNama\" FROM pengajuan_penundaan d JOIN tagihan t ON t.id=d.tagihan_id JOIN booking b ON b.id=t.booking_id JOIN kamar km ON km.id=b.kamar_id JOIN kos k ON k.id=km.kos_id JOIN pengguna p ON p.id=b.penyewa_id WHERE k.pemilik_id=? ORDER BY d.dibuat_pada DESC",uid); return db.queryForList("SELECT d.id,d.tagihan_id AS \"tagihanId\",d.tanggal_diminta AS \"tanggalDiminta\",d.alasan,d.status,d.catatan_pemilik AS \"catatanPemilik\",d.dibuat_pada AS \"dibuatPada\",t.periode,t.jatuh_tempo AS \"jatuhTempo\",t.total,t.total-t.terbayar AS sisa,km.nomor AS \"kamarNomor\",k.nama AS \"kosNama\" FROM pengajuan_penundaan d JOIN tagihan t ON t.id=d.tagihan_id JOIN booking b ON b.id=t.booking_id JOIN kamar km ON km.id=b.kamar_id JOIN kos k ON k.id=km.kos_id WHERE b.penyewa_id=? ORDER BY d.dibuat_pada DESC",uid); }
    @PatchMapping("/penundaan/{id}") Map<String,Object> decideDelay(HttpSession s,@PathVariable long id,@RequestBody Map<String,String> body) { long uid=ownerId(s); if(!List.of("DISETUJUI","DITOLAK").contains(body.get("status"))) throw new IllegalArgumentException("Status pengajuan tidak valid."); int changed=db.update("UPDATE pengajuan_penundaan d SET status=?,catatan_pemilik=? FROM tagihan t,booking b,kamar km,kos k WHERE d.id=? AND d.status='MENUNGGU' AND t.id=d.tagihan_id AND b.id=t.booking_id AND km.id=b.kamar_id AND k.id=km.kos_id AND k.pemilik_id=?",body.get("status"),body.get("catatanPemilik"),id,uid); if(changed==0) throw new IllegalArgumentException("Pengajuan tidak ditemukan, bukan milik kos kamu, atau sudah diproses."); return db.queryForMap("SELECT * FROM pengajuan_penundaan WHERE id=?",id); }
    @GetMapping("/kos/{kosId}/keluhan") List<Map<String,Object>> ownerComplaints(HttpSession s,@PathVariable long kosId) { long uid=ownerId(s); requireOwnedKos(kosId,uid); return db.queryForList("SELECT q.id,q.kategori,q.deskripsi,q.status,q.tanggapan_pemilik AS \"tanggapanPemilik\",q.dibuat_pada AS \"dibuatPada\",q.diperbarui_pada AS \"diperbaruiPada\",km.nomor AS \"kamarNomor\",p.nama AS \"penyewaNama\" FROM keluhan q JOIN booking b ON b.id=q.booking_id JOIN kamar km ON km.id=b.kamar_id JOIN pengguna p ON p.id=b.penyewa_id WHERE km.kos_id=? ORDER BY q.dibuat_pada",kosId); }
    @DeleteMapping("/keluhan/{id}") ResponseEntity<Void> deleteComplaint(HttpSession s,@PathVariable long id) { int n=db.update("DELETE FROM keluhan q USING booking b WHERE q.id=? AND b.id=q.booking_id AND b.penyewa_id=? AND q.status='DILAPORKAN'",id,user(s)); if(n==0) throw new IllegalArgumentException("Keluhan tidak dapat dihapus setelah mulai diproses."); return ResponseEntity.noContent().build(); }
    @PatchMapping("/admin/kos/{id}/nonaktif") Map<String,Object> deactivateKos(HttpSession s,@PathVariable long id,@RequestBody Map<String,String> body) { admin(s); db.update("UPDATE kos SET status_verifikasi='DINONAKTIFKAN',catatan_verifikasi=? WHERE id=?",body.get("alasan"),id); return db.queryForMap("SELECT * FROM kos WHERE id=?",id); }
}
